#!/usr/bin/env node
/* Builds the generated files under shared/ (design v2):
 *   design/fonts.js              base64 Instrument Serif + Geist Mono, registers them via the FontFace API (global MeetingPlzFonts)
 *   reminder/reminder.iife.js    reminder.js as a plain script (global MeetingPlzReminder), with fonts.js prepended
 *   art/plane.svg, art/clouds.svg, art/icon.svg, art/icon-paper.svg   (and icon PNGs with --png; needs `sharp`, auto-found in ~/.aside/cn-tools or node_modules)
 * Usage:  node shared/build.js            (fonts.js + IIFE + SVGs)
 *         node shared/build.js --png      (also renders icon PNGs)
 */
'use strict';
const fs = require('fs');
const path = require('path');

const dir = __dirname;

/* ---- fonts.js ---- */
const FACES = [
  ['MPZ Serif', 'normal', '400', 'InstrumentSerif-Regular'],
  ['MPZ Serif', 'italic', '400', 'InstrumentSerif-Italic'],
  ['MPZ Mono', 'normal', '400', 'GeistMono-Regular'],
  ['MPZ Mono', 'normal', '500', 'GeistMono-Medium']
];
const faceData = FACES.map(([fam, style, weight, file]) => [fam, style, weight, fs.readFileSync(path.join(dir, 'design/fonts', file + '.woff2')).toString('base64')]);
const fontsJs =
  '/* MeetingPlz fonts (generated by shared/build.js from design/fonts/*.woff2; do not edit).\n' +
  ' * Instrument Serif and Geist Mono, both SIL OFL 1.1 (design/fonts/OFL-*.txt). Latin subset, woff2, base64.\n' +
  ' * @font-face does not work inside a shadow root, so the reminder registers the faces on the page with the FontFace API:\n' +
  ' *   MeetingPlzFonts.register() -> Promise. Families: "MPZ Serif" (400, 400 italic), "MPZ Mono" (400, 500). Idempotent. */\n' +
  '(function (root, factory) {\n' +
  "  if (typeof module === 'object' && module.exports) module.exports = factory(root);\n" +
  '  else root.MeetingPlzFonts = factory(root);\n' +
  "})(typeof self !== 'undefined' ? self : this, function (root) {\n" +
  "  'use strict';\n" +
  '  var FACES = ' + JSON.stringify(faceData) + ';\n' +
  '  function bytes(b64) { var bin = root.atob(b64), n = bin.length, u = new Uint8Array(n); for (var i = 0; i < n; i++) u[i] = bin.charCodeAt(i); return u; }\n' +
  '  function register() {\n' +
  '    if (root.__mpzFonts) return root.__mpzFonts;\n' +
  "    if (!root.FontFace || !root.document || !root.document.fonts || !root.atob) return Promise.resolve([]);\n" +
  '    var have = {};\n' +
  "    try { root.document.fonts.forEach(function (x) { have[String(x.family).replace(/[\\\"']/g, '') + '|' + x.style + '|' + x.weight] = x; }); } catch (e) {}\n" +
  '    var jobs = FACES.map(function (f) {\n' +
  "      var ex = have[f[0] + '|' + f[1] + '|' + f[2]];\n      if (ex) return ex.load().catch(function () { return null; });\n" +
  '      try {\n' +
  "        var face = new root.FontFace(f[0], bytes(f[3]).buffer, { style: f[1], weight: f[2], display: 'swap' });\n" +
  '        root.document.fonts.add(face);\n' +
  '        return face.load().catch(function () { return null; });\n' +
  '      } catch (e) { return Promise.resolve(null); }\n' +
  '    });\n' +
  '    root.__mpzFonts = Promise.all(jobs);\n' +
  '    return root.__mpzFonts;\n' +
  '  }\n' +
  "  return { register: register, FAMILIES: { serif: 'MPZ Serif', mono: 'MPZ Mono' }, FACES: FACES.map(function (f) { return f.slice(0, 3); }) };\n" +
  '});\n';
fs.writeFileSync(path.join(dir, 'design/fonts.js'), fontsJs);

/* ---- IIFE ---- */
const src = fs.readFileSync(path.join(dir, 'reminder/reminder.js'), 'utf8');
const names = [];
let body = src
  .replace(/^export default [^;]*;\s*$/m, '')
  .replace(/^export (function|const|var|let) ([A-Za-z_$][\w$]*)/gm, (m, kind, name) => { names.push(name); return kind + ' ' + name; });
const api = names.filter((n) => !/^PLANE_/.test(n)).concat(['PLANE_VIEWBOX', 'PLANE_INNER']);
const iife =
  '/* MeetingPlz reminder (generated by shared/build.js from reminder.js; do not edit). Global: MeetingPlzReminder */\n' +
  fontsJs +
  '(function (root) {\n"use strict";\n' + body + '\nroot.MeetingPlzReminder = { ' + api.map((n) => n + ': ' + n).join(', ') + ' };\n' +
  '})(typeof self !== "undefined" ? self : this);\n';
fs.writeFileSync(path.join(dir, 'reminder/reminder.iife.js'), iife);

/* ---- art ---- */
const PLANE_VIEWBOX = /PLANE_VIEWBOX = '([^']+)'/.exec(src)[1];
const planeInner = eval(src.match(/export const PLANE_INNER =([\s\S]*?);\n/)[1]);
const INK = '#171512', PAPER = '#F3EFE6', SURFACE = '#FBF9F4', ACCENT = '#D4512A', ACCENT_DARK = '#EE6A40';
const attrs = `fill="none" stroke="${INK}" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"`;
fs.mkdirSync(path.join(dir, 'art'), { recursive: true });
fs.writeFileSync(path.join(dir, 'art/plane.svg'),
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${PLANE_VIEWBOX}" ${attrs}>${planeInner}</svg>\n`);

// Empty state: the plane over two clouds. Clear skies.
function cloud(x, y, s) {
  // flat-bottomed cloud outline, bottom-left corner at (x, y), ~120*s wide
  return `<path transform="translate(${x} ${y}) scale(${s})" d="M0 0 H112 C128 0 138 -11 138 -24 C138 -37 127 -47 113 -47 C110 -62 97 -73 81 -73 C65 -73 53 -64 49 -51 C45 -53 40 -54 35 -54 C20 -54 9 -43 9 -29 C3 -26 -4 -18 -4 -9 C-4 -3 -2 0 0 0 Z" fill="${SURFACE}"/>`;
}
const cloudsSvg =
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 190" ${attrs}>` +
  `<g transform="translate(94 14) scale(.62)">${planeInner}</g>` +
  `<path d="M20 74 H80" stroke-dasharray="1 7" stroke-width="2.4"/><path d="M34 88 H70" stroke-dasharray="1 7" stroke-width="2.4"/>` +
  cloud(176, 124, .78) + cloud(34, 168, 1.1) +
  `</svg>\n`;
fs.writeFileSync(path.join(dir, 'art/clouds.svg'), cloudsSvg);

// App icon: plane (viewBox 240x100) centred on a 1024 square, tilted up a little. Ink square + paper line art + accent tail stripe.
function icon({ stroke, detail = true, tilt = -9, scale = 3.6, bg = 'ink', size = 1024 }) {
  const line = bg === 'ink' ? PAPER : INK;
  const fill = bg === 'ink' ? INK : PAPER;
  const accent = bg === 'ink' ? ACCENT_DARK : ACCENT;
  let inner = planeInner.replace(/fill="#FBF9F4"/g, `fill="${fill}"`).replace(/fill="#D4512A"/g, `fill="${accent}"`);
  if (detail) inner = inner.replace(/(<path d="M56 53[^>]*?)stroke-width="4.2"/, `$1stroke-width="${(stroke * 2.3).toFixed(2)}"`);
  else inner = inner.replace(/<path d="M56 53[^>]*\/>/, '').replace(/<path d="M186 44[^>]*\/>/, '').replace(/<path d="M120 72.5[^>]*\/>/, '');
  const tx = 512 - 122.5 * scale, ty = 512 - 50 * scale;
  const border = bg === 'ink' ? '' : `<rect x="12" y="12" width="1000" height="1000" rx="228" fill="none" stroke="${INK}" stroke-width="10"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 1024 1024">\n` +
    `<rect width="1024" height="1024" rx="232" fill="${fill}"/>${border}\n` +
    `<g transform="rotate(${tilt} 512 512) translate(${tx} ${ty}) scale(${scale})" fill="none" stroke="${line}" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round">${inner}</g>\n</svg>\n`;
}

const variants = {
  1024: { stroke: 3.7 }, 512: { stroke: 3.9 }, 192: { stroke: 4.8 }, 180: { stroke: 5 }, 32: { stroke: 7, detail: false, scale: 3.8 }
};
fs.writeFileSync(path.join(dir, 'art/icon.svg'), icon({ stroke: 3.7 }));
fs.writeFileSync(path.join(dir, 'art/icon-paper.svg'), icon({ stroke: 3.7, bg: 'paper' }));

function findSharp() {
  const cands = ['sharp', path.join(process.env.HOME || '', '.aside/cn-tools/node_modules/sharp')];
  for (const c of cands) { try { return require(c); } catch (e) {} }
  return null;
}

(async () => {
  if (process.argv.includes('--png')) {
    const sharp = findSharp();
    if (!sharp) { console.error('sharp not found; skipping PNG render'); return; }
    for (const [size, v] of Object.entries(variants)) {
      const svg = icon(Object.assign({ size: +size }, v));
      await sharp(Buffer.from(svg), { density: 72 * (+size / 1024) < 72 ? 300 : 72 }).resize(+size, +size).png().toFile(path.join(dir, `art/icon-${size}.png`));
    }
    await sharp(Buffer.from(icon({ stroke: 3.7, bg: 'paper' }))).resize(1024, 1024).png().toFile(path.join(dir, 'art/icon-paper-1024.png'));
  }
  console.log('built design/fonts.js, reminder.iife.js (' + iife.length + ' bytes), art svgs' + (process.argv.includes('--png') ? ', pngs' : ''));
})();
